class Solution:
    def canMakeEqual(self, nums, k):
        n = len(nums)
        def ops(target):
            f = 0; res = 0
            for i in range(n - 1):
                cur = nums[i] * (-1 if f else 1)
                if cur != target:
                    f ^= 1; res += 1
            if nums[-1] * (-1 if f else 1) != target:
                return float('inf')
            return res
        return min(ops(1), ops(-1)) <= k

