class Solution {
public:
    bool canMakeEqual(vector<int>& nums, int k) {
        int n = nums.size();
        auto ops = [&](int target) {
            int f = 0; long long res = 0;
            for (int i = 0; i + 1 < n; i++) {
                int cur = nums[i] * (f ? -1 : 1);
                if (cur != target) { f ^= 1; res++; }
            }
            if (nums[n-1] * (f ? -1 : 1) != target) return LLONG_MAX;
            return res;
        };
        return min(ops(1), ops(-1)) <= (long long)k;
    }
};

