class Solution {
    public boolean canMakeEqual(int[] nums, int k) {
        int n = nums.length;
        java.util.function.IntUnaryOperator dummy = null;
        class H { long ops(int target) {
            int f = 0; long res = 0;
            for (int i = 0; i + 1 < n; i++) {
                int cur = nums[i] * (f == 1 ? -1 : 1);
                if (cur != target) { f ^= 1; res++; }
            }
            if (nums[n-1] * (f == 1 ? -1 : 1) != target) return Long.MAX_VALUE;
            return res;
        }}
        H h = new H();
        return Math.min(h.ops(1), h.ops(-1)) <= (long) k;
    }
}

