var canMakeEqual = function(nums, k) {
    const n = nums.length;
    const ops = (target) => {
        let f = 0, res = 0;
        for (let i = 0; i + 1 < n; i++) {
            const cur = nums[i] * (f ? -1 : 1);
            if (cur !== target) { f ^= 1; res++; }
        }
        if (nums[n-1] * (f ? -1 : 1) !== target) return Infinity;
        return res;
    };
    return Math.min(ops(1), ops(-1)) <= k;
};
